package br.com.confirmacao.user.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.shared.api.PageResponse;import br.com.confirmacao.user.application.UserManagementService;import jakarta.servlet.http.HttpServletRequest;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.Pageable;import org.springframework.data.web.PageableDefault;import org.springframework.http.ResponseEntity;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/admin/users") public class UserManagementController{private final UserManagementService service;public UserManagementController(UserManagementService s){service=s;}@GetMapping public PageResponse<UserResponse> all(@ParameterObject@PageableDefault(size=20,sort="name")Pageable p){return PageResponse.from(service.findAll(p).map(UserResponse::from));}}
